package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for TarUtils.parseName
 */
public class TarUtils_parseName_TriageGen0Test {

    @Test
    public void testParseName_NormalString() {
        byte[] buffer = "testname".getBytes();
        String result = TarUtils.parseName(buffer, 0, buffer.length);
        assertEquals("testname", result);
    }

    @Test
    public void testParseName_WithNullTerminator() {
        // Test that it stops at the first 0 byte
        byte[] buffer = {'a', 'b', 'c', 0, 'd', 'e'};
        String result = TarUtils.parseName(buffer, 0, buffer.length);
        assertEquals("abc", result);
    }

    @Test
    public void testParseName_WithOffset() {
        // Test that it respects the offset
        byte[] buffer = {'x', 'y', 'z', 'a', 'b', 'c'};
        String result = TarUtils.parseName(buffer, 3, 3);
        assertEquals("abc", result);
    }

    @Test
    public void testParseName_WithLengthLimitation() {
        // Test that it respects the length parameter even if no null terminator is present
        byte[] buffer = {'a', 'b', 'c', 'd', 'e'};
        String result = TarUtils.parseName(buffer, 1, 2);
        assertEquals("bc", result);
    }

    @Test
    public void testParseName_EmptyRange() {
        byte[] buffer = {'a', 'b', 'c'};
        String result = TarUtils.parseName(buffer, 1, 0);
        assertEquals("", result);
    }

    @Test
    public void testParseName_OnlyNullTerminator() {
        byte[] buffer = {0, 0, 0};
        String result = TarUtils.parseName(buffer, 0, 3);
        assertEquals("", result);
    }

    @Test
    public void testParseName_NullTerminatorAtEnd() {
        byte[] buffer = {'h', 'e', 'l', 'l', 'o', 0};
        String result = TarUtils.parseName(buffer, 0, 6);
        assertEquals("hello", result);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testParseName_OffsetOutOfBounds() {
        byte[] buffer = {'a', 'b'};
        TarUtils.parseName(buffer, 5, 1);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testParseName_LengthOutOfBounds() {
        byte[] buffer = {'a', 'b'};
        TarUtils.parseName(buffer, 0, 5);
    }
}
